// Plain `codex debug models` returns the effective catalog, which includes
// our own merged file (Codex loads it via model_catalog_json). The fake
// binary below reproduces that: --bundled is pristine, plain is polluted
// with a stale declared model. Capture must prefer --bundled so removed
// models never resurrect in the native cache.
function writeFakeCodexBin(dir, { failBundled = false } = {}) {
  const fakeBin = path.join(dir, "codex");
  writeFileSync(
    fakeBin,
    `#!/usr/bin/env bun
const args = process.argv.slice(2);
if (${failBundled ? "true" : "false"} && args.includes("--bundled")) process.exit(1);
const pristine = { models: [{ slug: "gpt-5.6-sol", display_name: "GPT-5.6 Sol", visibility: "list", priority: 1, supported_in_api: true }] };
const polluted = { models: [...pristine.models, { slug: "deepseek-flash", display_name: "V4 Flash", visibility: "list", priority: 1, supported_in_api: true }] };
console.log(JSON.stringify(args.includes("--bundled") ? pristine : polluted));
`,
  );
  chmodSync(fakeBin, 0o755);
  return fakeBin;
}

test("native capture prefers the pristine bundled catalog", async () => {
  const dir = mkdtempSync(path.join(tmpdir(), "codextras-codex-bin-"));
  delete process.env.CODEXTRAS_NATIVE_CATALOG;
  process.env.CODEXTRAS_CODEX_BIN = writeFakeCodexBin(dir);
  try {
    const { captureNativeCatalog } = await import("../src/catalog.mjs");
    const captured = captureNativeCatalog();
    expect(captured.models.map((m) => m.slug)).toEqual(["gpt-5.6-sol"]);
  } finally {
    delete process.env.CODEXTRAS_CODEX_BIN;
  }
});

test("native capture falls back to plain models when --bundled fails", async () => {
