  delete process.env.CODEXTRAS_NATIVE_CATALOG;
  process.env.CODEXTRAS_CODEX_BIN = writeFakeCodexBin(dir, { failBundled: true });
  try {
    const { captureNativeCatalog } = await import("../src/catalog.mjs");
    const captured = captureNativeCatalog();
    expect(captured.models.map((m) => m.slug).sort()).toEqual([
      "deepseek-flash",
      "gpt-5.6-sol",
    ]);
  } finally {
    delete process.env.CODEXTRAS_CODEX_BIN;
  }
});

test("removed declared models do not resurrect in the merged catalog", async () => {
