  process.env.CODEXTRAS_CODEX_BIN = writeFakeCodexBin(dir);
  try {
    const { loadConfig } = await import("../src/config.mjs");
    const { mergeCatalog, captureNativeCatalog } = await import("../src/catalog.mjs");
    // The test config declares test-model/text-model only: deepseek-flash
    // exists solely in the polluted plain output and must stay out.
    const merged = mergeCatalog(loadConfig(), captureNativeCatalog());
    const slugs = merged.models.map((m) => m.slug);
    expect(slugs).not.toContain("deepseek-flash");
    expect(slugs).toContain("test-model");
    expect(merged.models.find((m) => m.slug === "test-model").display_name).toBe(
      "Test Model",
    );
  } finally {
    delete process.env.CODEXTRAS_CODEX_BIN;
  }
});

