bun -e '
const p = Buffer.from(JSON.stringify({hi:1}));
console.log("zstd", typeof Bun.zstdCompressSync, typeof Bun.zstdDecompressSync);
console.log("gzip", typeof Bun.gzipSync, typeof Bun.gunzipSync);
console.log("deflate", typeof Bun.deflateSync, typeof Bun.inflateSync);
// test roundtrips
for (const [name, enc, dec] of [
  ["zstd", (b)=>Bun.zstdCompressSync(b), (b)=>Bun.zstdDecompressSync(b)],
  ["gzip", (b)=>Bun.gzipSync(b), (b)=>Bun.gunzipSync(b)],
  ["deflate", (b)=>Bun.deflateSync(b), (b)=>Bun.inflateSync(b)],
]) {
  try {
    const c = enc(p);
    const d = dec(c);
    console.log(name, "roundtrip ok", Buffer.from(d).toString());
  } catch(e){ console.log(name, "fail", e.message); }
}
// brotli via node:zlib?
import * as z from "node:zlib";
try {
  const c = z.brotliCompressSync(p);
  const d = z.brotliDecompressSync(c);
  console.log("brotli roundtrip ok", d.toString());
} catch(e){ console.log("brotli fail", e.message); }
'

