import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { createMockProvider } from "./smoke/mock-provider.mjs";
const mock = createMockProvider();
const dir = mkdtempSync(path.join(tmpdir(), "codextras-repro-"));
const configPath = path.join(dir, "codextras.json");
writeFileSync(configPath, JSON.stringify({
  gateway: { port: 0, pathPrefix: "/_codextras" },
  providers: [{ id: "mock", type: "openai-chat", baseUrl: "http://127.0.0.1:"+mock.port, apiKeyEnv: "CODEXTRAS_TEST_KEY", quirks: { efforts: {low:"low",high:"high",max:"max"} } }],
  models: [{ alias: "test-model", displayName: "Test", provider: "mock", upstreamModel: "mock-upstream", contextWindow: 100000, efforts: ["low","high","max"], defaultEffort: "high", inputModalities: ["text","image"], reasoningContent: true }]
}));
process.env.CODEXTRAS_TEST_KEY="sk-test";
process.env.CODEXTRAS_CONFIG=configPath;
const { createServer } = await import("./src/server.mjs");
const { loadConfig } = await import("./src/config.mjs");
const secret="testsecret123";
const server = createServer(loadConfig(), secret);
const base = `http://127.0.0.1:${server.port}/_codextras/${secret}`;
function user(text){ return { type: "message", role: "user", content: [{ type: "input_text", text }] }; }
const payload = JSON.stringify({ model: "test-model", input: [user("hi")], stream: false });
console.log("plain test");
let res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json"}, body: payload});
console.log("plain status", res.status, (await res.text()).slice(0,500));
// zstd test
const compressed = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload)));
console.log("zstd len", compressed.length);
res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json", "Content-Encoding":"zstd"}, body: compressed});
console.log("zstd status", res.status);
console.log((await res.text()).slice(0,1000));
// gzip test
const gz = Buffer.from(Bun.gzipSync(Buffer.from(payload)));
res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json", "Content-Encoding":"gzip"}, body: gz});
console.log("gzip status", res.status);
console.log((await res.text()).slice(0,1000));
server.stop(true); mock.stop(true);
EOF
bun /tmp/repro.mjs

