UTIL:
import { randomUUID } from "node:crypto";

export function uuid() {
  return randomUUID().replaceAll("-", "");
}

export function newId(prefix) {
  return prefix + "_" + uuid();
}

export function messageItem(text) {
  return { type: "message", role: "user", content: [{ type: "input_text", text }] };
}

export function sse(type, data, sequence) {
  const payload = { type: type, ...data };
  if (sequence !== undefined) payload.sequence_number = sequence;
  return "event: " + type + "\ndata: " + JSON.stringify(payload) + "\n\n";
}

export function sseDone() {
  return "data: [DONE]\n\n";
}

export const COMPACTION_PREFIX = "kcr1:";

export const SUMMARY_PREFIX =
  "Another language model started this task and produced a continuation summary. Use it to continue without repeating completed work:";

export const COMPACT_PROMPT =
  "You are performing a CONTEXT CHECKPOINT COMPACTION. Create a handoff summary for another language model that will resume the task.\n\n" +
  "Include current progress, key decisions, constraints, user preferences, remaining steps, and critical data or references. Be concise, structured, and focused on seamless continuation.";

export function encodeSummary(summary) {
  return COMPACTION_PREFIX + Buffer.from(summary, "utf8").toString("base64");
}

export function decodeSummary(value) {
  if (typeof value !== "string" || !value.startsWith(COMPACTION_PREFIX)) return undefined;
  try {
    return Buffer.from(value.slice(COMPACTION_PREFIX.length), "base64").toString("utf8");
  } catch {
    return undefined;
  }
}

export function textOf(item) {
  if (!item || !Array.isArray(item.content)) return "";
  return item.content
    .map((part) => (part && typeof part.text === "string" ? part.text : ""))
    .join("");
}

export function reasoningItemText(item) {
  const summary = item && item.summary;
  if (typeof summary === "string" && summary) return summary;
  if (Array.isArray(summary)) {
    const text = summary
      .map((part) => (part && typeof part.text === "string" ? part.text : undefined))
      .filter(Boolean)
      .join("\n");
    if (text) return text;
  }
  const content = item && item.content;
  if (typeof content === "string" && content) return content;
  if (Array.isArray(content)) {
    const text = content
      .map((part) => (part && typeof part.text === "string" ? part.text : undefined))
      .filter(Boolean)
      .join("\n");
    if (text) return text;
  }
  return undefined;
}

// Native OpenAI encrypted tokens are dense base64-ish blobs with no spaces.
// Routed handoffs are stored as readable plaintext; only those are inlinable.
export function isOpaqueToken(value) {
  return typeof value === "string" && value.length > 40 && !/\s/.test(value);
}

export function estimateTokensFromBytes(bytes) {
  return Math.max(1, Math.ceil(bytes / 4));
}

export function estimateTokensFromText(text) {
  const bytes = Buffer.byteLength(text || "", "utf8");
  return Math.max(0, Math.ceil(bytes / 4));
}

NATIVE:
// Native OpenAI passthrough: requests for models that are not declared in
// codextras.json are forwarded to the signed-in ChatGPT backend, exactly like
// codex-router does, so OpenAI models keep working alongside routed models.

const FORWARD_HEADERS = new Set([
  "authorization",
  "chatgpt-account-id",
  "openai-beta",
  "originator",
  "session_id",
  "session-id",
  "thread-id",
  "x-client-request-id",
  "x-codex-beta-features",
  "x-codex-installation-id",
  "x-codex-parent-thread-id",
  "x-codex-turn-metadata",
  "x-codex-turn-state",
  "x-codex-window-id",
  "x-oai-attestation",
  "x-openai-subagent",
  "x-responsesapi-include-timing-metrics",
]);

export function nativeBase() {
  return String(
    process.env.CODEXTRAS_NATIVE_BASE_URL ||
      "https://chatgpt.com/backend-api/codex",
  ).replace(/\/+$/, "");
}

export function nativeTarget(apiPath, search) {
  const withoutV1 = apiPath.replace(/^\/v1(?=\/|$)/, "");
  return nativeBase() + withoutV1 + (search || "");
}

export function forwardedHeaders(request) {
  const headers = {
    "Content-Type": "application/json",
    "Accept-Encoding": "identity",
  };
  for (const name of FORWARD_HEADERS) {
    const value = request.headers.get(name);
    if (value !== undefined && value !== null && value !== "") {
      headers[name] = value;
    }
  }
  return headers;
}

export async function forwardNative(request, apiPath, rawBody) {
  const url = new URL(request.url);
  const target = nativeTarget(apiPath, url.search);
  const body = rawBody !== undefined ? rawBody : undefined;
  let res;
  try {
    res = await fetch(target, {
      method: request.method,
      headers: forwardedHeaders(request),
      body: request.method === "GET" ? undefined : body,
      signal: request.signal,
    });
  } catch (error) {
    const message = error && error.message ? error.message : String(error);
    return Response.json({ error: { message } }, { status: 502 });
  }
  const responseHeaders = new Headers();
  const contentType = res.headers.get("content-type");
  if (contentType) responseHeaders.set("content-type", contentType);
  return new Response(res.body, { status: res.status, headers: responseHeaders });
}

COMPACTION:
import {
  COMPACT_PROMPT,
  SUMMARY_PREFIX,
  encodeSummary,
  messageItem,
  newId,
  sse,
  sseDone,
} from "./util.mjs";
import { buildMessages, buildResponsesInput, userMessageTexts } from "./convert/request.mjs";
import {
  buildChatBody,
  buildResponsesBody,
  chatUrl,
  isResponsesModel,
  providerHeaders,
  responsesUrl,
  supportsResponsesCustomTools,
} from "./adapter.mjs";
import { fallbackFrom, finalizeUsage } from "./usage.mjs";

function extractResponseText(json) {
  const message = json && json.choices && json.choices[0] && json.choices[0].message;
  if (message && typeof message.content === "string") return message.content;
  if (typeof json.output_text === "string") return json.output_text;
  let text = "";
  for (const item of Array.isArray(json && json.output) ? json.output : []) {
    for (const part of Array.isArray(item && item.content) ? item.content : []) {
      if (part && (part.type === "output_text" || part.type === "text") && typeof part.text === "string") {
        text += part.text;
      }
    }
  }
  return text;
}

export async function summarize({ payload, model, provider, requestBytes, signal }) {
  const isResponses = isResponsesModel(model, provider);
  let body;
  let url;
  if (isResponses) {
    const base = buildResponsesInput({
      input: Array.isArray(payload.input) ? payload.input : [],
      model,
      supportsCustomTools: supportsResponsesCustomTools(model, provider),
    });
    base.push({ type: "message", role: "user", content: [{ type: "input_text", text: COMPACT_PROMPT }] });
    body = buildResponsesBody({ payload, model, provider, input: base, tools: [], stream: false });
    url = responsesUrl(provider);
  } else {
    const messages = buildMessages({ input: payload.input || [], model });
    messages.push({ role: "user", content: [{ type: "text", text: COMPACT_PROMPT }] });
    body = buildChatBody({ payload, model, provider, messages, tools: [], stream: false });
    url = chatUrl(provider);
  }
  let res;
  try {
    res = await fetch(url, {
      method: "POST",
      headers: providerHeaders(provider),
      body: JSON.stringify(body),
      signal,
    });
  } catch (error) {
    const message = error && error.message ? error.message : String(error);
    return { ok: false, status: 502, payload: { error: { message } } };
  }
  const json = await res.json().catch(() => ({}));
  if (!res.ok) {
    const message =
      json && json.error && json.error.message
        ? json.error.message
        : "Upstream compaction failed with " + res.status;
    return { ok: false, status: res.status, payload: { error: { message } } };
  }
  const summary = extractResponseText(json).trim();
  if (!summary) {
    return {
      ok: false,
      status: 502,
      payload: { error: { message: "Compaction produced no summary." } },
    };
  }
  const usage = finalizeUsage(json.usage, fallbackFrom(requestBytes, summary));
  return { ok: true, summary, usage, input: payload.input || [] };
}

export function compactOutputV1(input, summary) {
  const budget = 80000;
  const selected = [];
  let remaining = budget;
  const texts = userMessageTexts(input);
  for (let i = texts.length - 1; i >= 0 && remaining > 0; i -= 1) {
    const value = texts[i];
    if (value.length <= remaining) {
      selected.push(value);
      remaining -= value.length;
    } else {
      selected.push(value.slice(value.length - remaining));
      break;
    }
  }
  selected.reverse();
  const summaryText = summary.trim()
    ? SUMMARY_PREFIX + "\n" + summary
    : "(no summary available)";
  return [...selected.map(messageItem), messageItem(summaryText)];
}

export function compactionSnapshot(model, item, status) {
  return {
    id: newId("resp"),
    object: "response",
    created_at: Math.floor(Date.now() / 1000),
    status: status || "completed",
    model,
    output: item ? [item] : [],
    usage: null,
  };
}

export function writeCompactionSseEvents(model, summary) {
  const item = {
    type: "compaction",
    id: newId("cmp"),
    encrypted_content: encodeSummary(summary),
  };
  const created = compactionSnapshot(model, undefined, "in_progress");
