652:  }
653:  const provider = providerFor(model, config);
654:  if (!provider) {
655:    return json({ error: { message: "No provider configured for " + model.alias } }, 500);
656:  }
657:  const bodyForBytes = JSON.stringify({
658:    model: model.alias,
659:    input: payload.input || [],
660:  });
