662:  const result = await summarize({
663:    payload,
664:    model,
665:    provider,
666:    requestBytes,
667:    signal: request.signal,
668:  });
669:  if (!result.ok) {
670:    return json(result.payload, result.status);
671:  }
672:  const inputs = Array.isArray(payload.input) ? payload.input : [];
673:  const compactionV2 =
674:    inputs.length > 0 && inputs[inputs.length - 1]?.type === "compaction_trigger";
675:  if (compactionV2) {
