\"application/json\", \"Content-Encoding\":\"zstd\"}, body: zstd});\nconsole.log(\"zstd\", res.status);\nconsole.log((await res.text()).slice(0,500));\nconst gz = Buffer.from(Bun.gzipSync(Buffer.from(payload)));\nres = await fetch(base+\"/v1/responses\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"gzip\"}, body: gz});\nconsole.log(\"gzip\", res.status, (await res.text()).slice(0,200));\nimport * as z from \"node:zlib\";\nconst br = z.brotliCompressSync(Buffer.from(payload));\nres = await fetch(base+\"/v1/responses\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"br\"}, body: br});\nconsole.log(\"br\", res.status, (await res.text()).slice(0,200));\nconst def = z.deflateSync(Buffer.from(payload));\nres = await fetch(base+\"/v1/responses\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"deflate\"}, body: def});\nconsole.log(\"deflate\", res.status, (await res.text()).slice(0,200));\n// zstd without header (sniff)\nres = await fetch(base+\"/v1/responses\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\"}, body: zstd});\nconsole.log(\"zstd-noheader\", res.status, (await res.text()).slice(0,500));\n// stream with zstd\nconst payload2 = JSON.stringify({ model: \"test-model\", input: [user(\"hi\")], stream: true });\nconst zstd2 = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload2)));\nres = await fetch(base+\"/v1/responses\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"zstd\"}, body: zstd2});\nconsole.log(\"zstd-stream\", res.status, res.headers.get(\"content-type\"));\nconst t = await res.text();\nconsole.log(t.slice(0,500));\nconsole.log(\"has completed\", t.includes(\"response.completed\"));\nserver.stop(true); mock.stop(true);\nEOF\nbun ./repro-tmp.mjs; rm ./repro-tmp.mjs', description: 'Test inbound fix'});
