writeFileSync(configPath, JSON.stringify({
  gateway: { port: 0, pathPrefix: "/_codextras" },
  providers: [{ id: "mock", type: "openai-chat", baseUrl: "http://127.0.0.1:"+mock.port, apiKeyEnv: "CODEXTRAS_TEST_KEY", quirks: { efforts: {low:"low",high:"high",max:"max"} } }],
  models: [{ alias: "test-model", displayName: "Test", provider: "mock", upstreamModel: "mock-upstream", contextWindow: 100000, efforts: ["low","high","max"], defaultEffort: "high", inputModalities: ["text","image"], reasoningContent: true }]
}));
process.env.CODEXTRAS_TEST_KEY="sk-test";
process.env.CODEXTRAS_CONFIG=configPath;
const { createServer } = await import("./src/server.mjs");
