const payload = JSON.stringify({ model: "test-model", input: [user("hi")], stream: false });
console.log("plain");
let res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json"}, body: payload});
console.log("plain", res.status, (await res.text()).slice(0,200));
const zstd = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload)));
console.log("zstd len", zstd.length);
res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json", "Content-Encoding":"zstd"}, body: zstd});
console.log("zstd", res.status);
console.log((await res.text()).slice(0,500));
const gz = Buffer.from(Bun.gzipSync(Buffer.from(payload)));
res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json", "Content-Encoding":"gzip"}, body: gz});
