const def = z.deflateSync(Buffer.from(payload));
res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json", "Content-Encoding":"deflate"}, body: def});
console.log("deflate", res.status, (await res.text()).slice(0,200));
// zstd without header (sniff)
res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json"}, body: zstd});
console.log("zstd-noheader", res.status, (await res.text()).slice(0,500));
// stream with zstd
const payload2 = JSON.stringify({ model: "test-model", input: [user("hi")], stream: true });
const zstd2 = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload2)));
res = await fetch(base+"/v1/responses", {method:"POST", headers: {"Content-Type":"application/json", "Content-Encoding":"zstd"}, body: zstd2});
