sponses\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"zstd\", \"Authorization\":\"Bearer x\"}, body: comp});\nconsole.log(\"native zstd:\", res.status, (await res.text()).slice(0,200));\n// 5. compaction with zstd\npayload = JSON.stringify({model:\"test-model\", input:[user(\"hello world\")]});\ncomp = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload)));\nres = await fetch(base+\"/v1/responses/compact\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"zstd\"}, body: comp});\nconsole.log(\"compact zstd:\", res.status, (await res.text()).slice(0,300));\n// 6. x-gzip alias\npayload = JSON.stringify({model:\"test-model\", input:[user(\"hi\")], stream:false});\nlet gz = Buffer.from(Bun.gzipSync(Buffer.from(payload)));\nres = await fetch(base+\"/v1/responses\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"x-gzip\"}, body: gz});\nconsole.log(\"x-gzip:\", res.status, res.status===200?\"PASS\":\"FAIL\");\n// 7. zstandard alias\ncomp = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload)));\nres = await fetch(base+\"/v1/responses\", {method:\"POST\", headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"zstandard\"}, body: comp});\nconsole.log(\"zstandard alias:\", res.status, res.status===200?\"PASS\":\"FAIL\");\nserver.stop(true); mock.stop(true); nativeMock.stop(true);\nEOF\nbun ./repro-edge.mjs; rm ./repro-edge.mjs', description: 'Test edge cases'});
